## solution

#### dynamic programming with memoization

```cpp
#include <string>
#include <vector>
#include <unordered_map>

int quickestConcat(std::string str, std::vector<std::string> words, std::unordered_map<std::string, int> &memo) {
  if (memo.count(str) > 0) {
    return memo[str];
  }

  if (str.length() == 0) {
    return 0;
  }

  int min = -1;

  for (std::string word : words) {
    if (str.find(word) == 0) {
      std::string suffix = str.substr(word.length());
      int suffixCount = quickestConcat(suffix, words, memo);
      if (suffixCount != -1) {
        int count = suffixCount + 1;
        if (min == -1 || count < min) {
          min = count;
        }
      }
    }
  }

  memo[str] = min;
  return min;
}

int quickestConcat(std::string str, std::vector<std::string> words) {
  std::unordered_map<std::string, int> memo;
  return quickestConcat(str, words, memo);
}
```

- s = length of string
- w = # of words
- Time: ~O(sw)
- Space: O(s)
